-- literature_seed_500_high_quality.sql
-- 校园学术文献智能检索与综述生成系统：500 条高质量模拟文献数据
-- 说明：本文件仅用于课程项目演示，所有文献、DOI、作者、链接均为模拟数据。
-- 本文件不会 DROP 表，也不会清空原有数据，只向 literature 表追加数据。
-- 请先执行 update_categories.sql，确保 category 表为 6 个一级分类 + 37 个二级分类。
-- category_id 仅使用二级分类 ID：7 到 43。
-- 导入方式：
-- mysql --default-character-set=utf8mb4 -u root -p
-- USE campus_literature_system;
-- SET NAMES utf8mb4;
-- source F:/campus-literature-system/database/literature_seed_500_high_quality.sql;

